cf4247297b005ea9fcb33a898bfe4bd7a6b480cf.source:
mutation login($emailAddress: EmailAddress!, $password: String!) {
  login(emailAddress: $emailAddress, password: $password) {
    __typename
    errorMessage
    message
    accountToken
    tokenExpiry
    me {
      __typename
      emailAddress
      phoneNumber
      firstName
      lastName
      userId
      company
      position
    }
  }
}

088ae4ee888ee72bc104772edcf0a15acc015932.source:
query me {
  me {
    __typename
    emailAddress
    phoneNumber
    firstName
    lastName
    userId
    company
    position
    activeOrganization {
      __typename
      id
      name
      roles
      permissions
      featureFlagMapping {
        __typename
        id
        active
        featureFlag {
          __typename
          id
          active
          featureIdentifier
        }
      }
    }
  }
}
